def walk(o,path,ptr=''):
 global all_string_count
 if isinstance(o,dict):
  for k,v in o.items():walk(v,path,ptr+'/'+str(k).replace('~','~0').replace('/','~1'))
 elif isinstance(o,list):
  for i,v in enumerate(o):walk(v,path,ptr+'/'+str(i))
 elif isinstance(o,str):
  all_string_count+=1
  if 'uses actual infinite-dimensional L²(J)' in o:old_hits.append(dict(path=path,pointer=ptr,value=o))
  if 'infinite' in o.lower() and any(x in o for x in ['L2','L²','L^2','L₂']):
   qualified=any(x in o for x in ['potentially infinite-dimensional','generally infinite dimensional','generally infinite-dimensional'])
   assert qualified,(path,ptr,o)
   dimension_fields.append(dict(path=path,pointer=ptr,value=o,classification='qualified possibility/general case, not an unconditional dimension claim'))
